"""Generate fast/lut_table.h from phycoweb/lut.py (feature 003, FR-007/FR-008, research R4).

The C fast stream must use exactly the reference model's perturbation table and constants.
`--check` exits 1 if the header on disk differs from what this script would write.
"""
import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from phycoweb.lut import COS_OFFSET, INC_A, INC_B, LUT_BITS, PERTURBATION_LUT  # noqa: E402

OUT = ROOT / "fast" / "lut_table.h"


def render() -> str:
    lines = [
        "/* GENERATED by scripts/gen_c_lut.py from phycoweb/lut.py - do not edit. */",
        "#ifndef PHYCO_LUT_TABLE_H",
        "#define PHYCO_LUT_TABLE_H",
        "#include <stdint.h>",
        "",
        f"#define LUT_BITS {LUT_BITS}",
        f"#define INC_A {INC_A}",
        f"#define INC_B {INC_B}",
        f"#define COS_OFFSET {COS_OFFSET}",
        "",
        f"static const uint16_t PERTURBATION_LUT[{len(PERTURBATION_LUT)}] = {{",
    ]
    for i in range(0, len(PERTURBATION_LUT), 8):
        lines.append("    " + ", ".join(f"0x{v:04X}" for v in PERTURBATION_LUT[i:i + 8]) + ",")
    lines += ["};", "", "#endif", ""]
    return "\n".join(lines)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    text = render()
    if args.check:
        current = OUT.read_text(encoding="ascii") if OUT.exists() else None
        if current != text:
            print(f"{OUT} is out of date; run scripts/gen_c_lut.py", file=sys.stderr)
            return 1
        print(f"{OUT} is up to date")
        return 0
    OUT.write_bytes(text.encode("ascii"))
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
